package org.jlinalg.genetics;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import org.jlinalg.genetics.FumaFisherFamilies.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class FumaFisherFamiliesTest {
    private static final Runnable CHECK=()->{};
    private static Table row(String family,String id,FumaFisherExact.Counts counts){return new Table(family,id,"trait","context",counts);}
    private static FumaFisherExact.Counts counts(long a,long b,long c,long d){return new FumaFisherExact.Counts(a,b,c,d);}
    private static Family family(String id,List<String> tests,Correction correction,Encoding encoding,Missing missing,Empty empty,int add){return new Family(id,tests,correction,encoding,missing,empty,add,.95);}
    private static Options options(){return new Options(.05,Limits.defaults());}
    private static Result fit(Family family,List<Table> rows){return FumaFisherFamilies.fit(List.of(family),rows,options(),CHECK);}
    private static List<String[]> resource(String name)throws Exception{try(var stream=FumaFisherFamiliesTest.class.getResourceAsStream("/fuma-fisher-families/"+name)){assertNotNull(stream);try(var reader=new BufferedReader(new InputStreamReader(stream,StandardCharsets.UTF_8))){return reader.lines().skip(1).map(line->line.split("\t",-1)).toList();}}}
    private static double numeric(String value){return switch(value){case "Inf"->Double.POSITIVE_INFINITY;case "-Inf"->Double.NEGATIVE_INFINITY;default->Double.parseDouble(value);};}
    private static void relative(double expected,double actual,double bound,String context){if(expected==0||!Double.isFinite(expected))assertEquals(expected,actual,context);else assertTrue(Double.isFinite(actual)&&Math.abs(actual-expected)/Math.abs(expected)<=bound,()->context+": expected="+expected+",actual="+actual+",relative="+Math.abs(actual-expected)/Math.abs(expected)+",bound="+bound);}
    @Test void allFortyCompleteOriginalRSourceFamiliesAndMissingPlaceholdersAgree()throws Exception {
        var input=resource("input.tsv");var reference=resource("reference.tsv");var declared=resource("families.tsv");assertEquals(8480,input.size());assertEquals(input.size(),reference.size());assertEquals(40,declared.size());var ids=new LinkedHashMap<String,List<String>>();var rows=new ArrayList<Table>();
        for(var r:input){ids.computeIfAbsent(r[0],ignored->new ArrayList<>()).add(r[1]);rows.add(new Table(r[0],r[1],r[2],r[3],r[4].equals("NA")?null:counts(Long.parseLong(r[4]),Long.parseLong(r[5]),Long.parseLong(r[6]),Long.parseLong(r[7]))));}
        var families=new ArrayList<Family>();for(var r:declared)families.add(new Family(r[0],ids.get(r[0]),Correction.valueOf(r[1]),Encoding.valueOf(r[2]),Missing.EXCLUDE,Empty.RETAIN_SOURCE,Integer.parseInt(r[3]),Double.parseDouble(r[4])));
        var result=FumaFisherFamilies.fit(families,rows,options(),CHECK);assertEquals(40,result.families().size());assertEquals(8480,result.tables().size());assertEquals(40,result.tables().stream().filter(t->t.status()==Status.MISSING_COUNTS).count());
        for(int i=0;i<reference.size();i++){
            var r=reference.get(i);var actual=result.tables().get(i);String context=r[0]+"/"+r[1];assertEquals(r[0],actual.table().family());assertEquals(r[1],actual.table().id());
            if(r[2].equals("NA")){assertNull(actual.fit());assertNull(actual.adjustedP());assertNull(actual.adjustedLogP());assertNull(actual.selected());continue;}
            relative(numeric(r[2]),actual.fit().pValue(),2e-14,context+" raw P");double q=numeric(r[4]),logQ=numeric(r[5]);
            if(actual.family().encoding()==Encoding.P_VALUE){relative(q,actual.adjustedP(),2e-14,context+" adjusted P");if(!Double.isFinite(logQ))assertEquals(logQ,actual.adjustedLogP());else assertTrue(Math.abs(Math.expm1(actual.adjustedLogP()-logQ))<=2e-14,context+" log of probability adjustment");}
            else{double gap=Math.abs(actual.adjustedLogP()-logQ);assertTrue(gap<=Math.max(16*Math.ulp(logQ),2e-14),context+" finite log adjustment");double induced=Math.abs(Math.expm1(actual.adjustedLogP()-logQ));relative(q,actual.adjustedP(),induced+(q==0?0:4*Math.ulp(q)/q),context+" exponentiated log adjustment");}
            assertEquals(Boolean.parseBoolean(r[6]),actual.selected(),context+" inclusive selection");
        }
        for(var audit:result.families()){assertEquals(1,audit.missingRows());assertEquals(audit.expectedRows(),audit.actualRows());assertEquals(audit.actualRows()-1,audit.availableRows());assertEquals(audit.availableRows(),audit.adjustmentSize());}
    }
    @Test void completeNullTestsChangeAdjustmentBeforeSelection(){var base=List.of(row("F","strong",counts(10,0,0,10)),row("F","weak",counts(4,0,0,4)));var two=fit(family("F",List.of("strong","weak"),Correction.BH,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,0),base);var four=new ArrayList<>(base);four.add(row("F","null1",counts(10,10,10,10)));four.add(row("F","null2",counts(10,10,10,10)));var full=fit(family("F",List.of("strong","weak","null1","null2"),Correction.BH,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,0),four);assertTrue(two.tables().get(1).selected());assertFalse(full.tables().get(1).selected());relative(4.0/70,full.tables().get(1).adjustedP(),2e-14,"full weak BH");assertEquals(4,full.families().get(0).adjustmentSize());}
    @Test void missingTableIsVisibleAndChangesOnlyTheAvailableDenominator(){var f=family("F",List.of("weak","missing"),Correction.BONFERRONI,Encoding.P_VALUE,Missing.EXCLUDE,Empty.ERROR,0);var r=fit(f,List.of(row("F","weak",counts(4,0,0,4)),row("F","missing",null)));assertEquals(2,r.families().get(0).expectedRows());assertEquals(1,r.families().get(0).adjustmentSize());assertEquals(Status.MISSING_COUNTS,r.tables().get(1).status());assertNull(r.tables().get(1).selected());assertTrue(r.warnings().stream().anyMatch(s->s.contains("not four observed zeros")));}
    @Test void missingCountsNeedExplicitExclusion(){var f=family("F",List.of("missing"),Correction.BH,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,0);assertTrue(assertThrows(IllegalArgumentException.class,()->fit(f,List.of(row("F","missing",null)))).getMessage().contains("EXCLUDE"));}
    @Test void everyPlannedIdMustExistEvenWhenMissing(){var f=family("F",List.of("a","b"),Correction.BH,Encoding.P_VALUE,Missing.EXCLUDE,Empty.ERROR,0);assertTrue(assertThrows(IllegalArgumentException.class,()->fit(f,List.of(row("F","a",counts(1,2,3,4))))).getMessage().contains("Incomplete declared"));}
    @Test void duplicateAndUndeclaredIdsAreRefused(){var r=row("F","a",counts(1,2,3,4));var f=family("F",List.of("a"),Correction.BH,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,0);assertThrows(IllegalArgumentException.class,()->fit(f,List.of(r,r)));assertThrows(IllegalArgumentException.class,()->fit(f,List.of(row("F","unknown",r.counts()))));assertThrows(IllegalArgumentException.class,()->fit(family("F",List.of("a","a"),Correction.BH,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,0),List.of(r)));assertThrows(IllegalArgumentException.class,()->FumaFisherFamilies.fit(List.of(f,f),List.of(r),options(),CHECK));}
    @Test void sameTestIdMayBelongToDifferentDeclaredFamilies(){var a=family("A",List.of("a"),Correction.BH,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,0);var b=family("B",List.of("a"),Correction.BONFERRONI,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,1);var r=FumaFisherFamilies.fit(List.of(a,b),List.of(row("B","a",counts(53,105,20,126)),row("A","a",counts(53,105,20,126))),options(),CHECK);assertEquals(List.of("B","A"),r.tables().stream().map(t->t.table().family()).toList());assertEquals(List.of("A","B"),r.families().stream().map(FamilyAudit::family).toList());assertNotEquals(r.tables().get(0).fit().pValue(),r.tables().get(1).fit().pValue());}
    @Test void emptyOriginalRowsNeedAnExplicitSourceRetentionChoice(){var counts=counts(0,0,57,340);var strict=family("F",List.of("a"),Correction.BH,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,1);assertTrue(assertThrows(IllegalArgumentException.class,()->fit(strict,List.of(row("F","a",counts)))).getMessage().contains("does not create observed associations"));var r=fit(family("F",List.of("a"),Correction.BH,Encoding.P_VALUE,Missing.ERROR,Empty.RETAIN_SOURCE,1),List.of(row("F","a",counts)));assertEquals(Status.EMPTY_ORIGINAL_GROUP_RETAINED,r.tables().get(0).status());assertEquals(counts,r.tables().get(0).fit().original());assertEquals(2,r.tables().get(0).fit().tested().finerNovel()+r.tables().get(0).fit().tested().finerKnown());assertTrue(r.warnings().stream().anyMatch(s->s.contains("do not establish an observed")));}
    @Test void finiteLogCorrectionRetainsUnderflowInsteadOfInventingAProbability(){var rows=List.of(row("F","a",counts(2000,0,0,2000)),row("F","b",counts(1,9,11,3)));var log=fit(family("F",List.of("a","b"),Correction.BONFERRONI,Encoding.NATURAL_LOG,Missing.ERROR,Empty.ERROR,0),rows);var p=fit(family("F",List.of("a","b"),Correction.BONFERRONI,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,0),rows);assertEquals(0,log.tables().get(0).adjustedP());assertTrue(Double.isFinite(log.tables().get(0).adjustedLogP()));assertEquals(Double.NEGATIVE_INFINITY,p.tables().get(0).adjustedLogP());assertTrue(Double.isFinite(p.tables().get(0).fit().logPValue()));assertEquals(1,log.families().get(0).adjustedProbabilityUnderflows());assertEquals(0,p.families().get(0).adjustedProbabilityUnderflows());}
    @Test void declaredZeroAndAllMissingFamiliesRemainExplicit(){var zero=family("zero",List.of(),Correction.BH,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,0);var r=fit(zero,List.of());assertEquals(0,r.families().get(0).availableRows());assertTrue(r.tables().isEmpty());assertTrue(r.warnings().stream().anyMatch(s->s.contains("EMPTY AVAILABLE FAMILY")));var missing=fit(family("F",List.of("a"),Correction.BH,Encoding.NATURAL_LOG,Missing.EXCLUDE,Empty.ERROR,0),List.of(row("F","a",null)));assertNull(missing.tables().get(0).adjustedLogP());}
    @Test void noneIsExplicitAndRetainsRawProbabilityValues(){var r=fit(family("F",List.of("a","b"),Correction.NONE,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,0),List.of(row("F","a",counts(1,9,11,3)),row("F","b",counts(4,0,0,4))));for(var table:r.tables())assertEquals(table.fit().pValue(),table.adjustedP());assertTrue(r.warnings().stream().anyMatch(s->s.contains("UNCORRECTED FAMILY")));}
    @Test void cutoffIsInclusiveInTheDeclaredRepresentation(){var c=counts(4,0,0,4);double p=FumaFisherExact.test(c,new FumaFisherExact.Options(0,.95,FumaFisherExact.Limits.defaults()),CHECK).pValue();var f=family("F",List.of("a"),Correction.NONE,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,0);var rows=List.of(row("F","a",c));assertTrue(FumaFisherFamilies.fit(List.of(f),rows,new Options(p,Limits.defaults()),CHECK).tables().get(0).selected());assertFalse(FumaFisherFamilies.fit(List.of(f),rows,new Options(Math.nextDown(p),Limits.defaults()),CHECK).tables().get(0).selected());}
    @Test void correctionDoesNotDropUnavailableOrUnselectedRows(){var f=family("F",List.of("a","b","c"),Correction.BONFERRONI,Encoding.P_VALUE,Missing.EXCLUDE,Empty.ERROR,0);var r=fit(f,List.of(row("F","c",null),row("F","b",counts(10,10,10,10)),row("F","a",counts(10,0,0,10))));assertEquals(List.of("c","b","a"),r.tables().stream().map(t->t.table().id()).toList());assertNull(r.tables().get(0).selected());assertFalse(r.tables().get(1).selected());assertTrue(r.tables().get(2).selected());}
    @Test void cumulativeSupportBudgetSpansAllFamilies(){var a=family("A",List.of("a"),Correction.NONE,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,0);var b=family("B",List.of("a"),Correction.NONE,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,0);var rows=List.of(row("A","a",counts(10,10,10,10)),row("B","a",counts(10,10,10,10)));var limits=new Limits(100,1000,21,41,1000000,1000);assertTrue(assertThrows(IllegalArgumentException.class,()->FumaFisherFamilies.fit(List.of(a,b),rows,new Options(.05,limits),CHECK)).getMessage().contains("support budget"));}
    @Test void operationAndInputBudgetsIncludeRegistriesAndFits(){var f=family("F",List.of("a"),Correction.NONE,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,0);var rows=List.of(row("F","a",counts(10,10,10,10)));assertThrows(IllegalArgumentException.class,()->FumaFisherFamilies.fit(List.of(f),rows,new Options(.05,new Limits(2,1000,100,1000,100000,1000)),CHECK));assertThrows(IllegalArgumentException.class,()->FumaFisherFamilies.fit(List.of(f),rows,new Options(.05,new Limits(100,1000,100,1000,20,1000)),CHECK));}
    @Test void testedPopulationIncludesPseudocountsBeforeAnyFit(){var f=family("F",List.of("a"),Correction.BH,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,1);assertThrows(IllegalArgumentException.class,()->FumaFisherFamilies.fit(List.of(f),List.of(row("F","a",counts(53,105,20,126))),new Options(.05,new Limits(100,307,200,1000,100000,1000)),CHECK));}
    @Test void cancellationPropagatesAcrossCompleteRun(){var f=family("F",List.of("a"),Correction.BH,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,0);var calls=new AtomicInteger();assertThrows(IllegalStateException.class,()->FumaFisherFamilies.fit(List.of(f),List.of(row("F","a",counts(1000,20,20,1000))),options(),()->{if(calls.incrementAndGet()>2)throw new IllegalStateException("cancelled");}));assertTrue(calls.get()>2);}
    @Test void invalidFamilyPoliciesAndIdentitiesAreRefused(){assertThrows(IllegalArgumentException.class,()->new Family("F",List.of("a"),null,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,0,.95));assertThrows(IllegalArgumentException.class,()->family("F\n",List.of("a"),Correction.BH,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,0));assertThrows(IllegalArgumentException.class,()->new Options(0,Limits.defaults()));assertThrows(IllegalArgumentException.class,()->new Family("F",List.of("a"),Correction.BH,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,-1,.95));assertThrows(IllegalArgumentException.class,()->new Family("F",List.of("a"),Correction.BH,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,0,1));assertThrows(IllegalArgumentException.class,()->new Limits(0,1,1,1,1,1));}
    @Test void resultPopulationsAndPoliciesAreImmutable(){var f=family("F",List.of("a"),Correction.BH,Encoding.P_VALUE,Missing.ERROR,Empty.ERROR,0);var r=fit(f,List.of(row("F","a",counts(1,2,3,4))));assertThrows(UnsupportedOperationException.class,()->r.tables().clear());assertThrows(UnsupportedOperationException.class,()->r.families().clear());assertThrows(UnsupportedOperationException.class,()->r.warnings().clear());assertThrows(UnsupportedOperationException.class,()->f.expectedTests().clear());assertTrue(r.operations()>r.supportStates());}
}
